{"command":"python3 << 'EOF'
import os, time, threading
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305

key = os.urandom(32)
nonce = os.urandom(12)
pt = os.urandom(40_000_000)
aad = os.urandom(32)

c = ChaCha20Poly1305(key)

def once():
    return c.encrypt(nonce, pt, aad)

# serial
for i in range(3):
    t0=time.perf_counter(); once(); print("serial", time.perf_counter()-t0)

# Does encrypt release GIL? parallel on SAME object may not be threadsafe.
# Use separate objects.
def worker(results, idx, n=1):
    cc = ChaCha20Poly1305(key)
    t0=time.perf_counter()
    for _ in range(n):
        results[idx]=cc.encrypt(nonce, pt, aad)
    results[idx]=time.perf_counter()-t0

for threads in (2,4,6):
    results=[None]*threads
    ts=[threading.Thread(target=worker, args=(results,i)) for i in range(threads)]
    t0=time.perf_counter()
    for t in ts: t.start()
    for t in ts: t.join()
    wall=time.perf_counter()-t0
    print(f"threads {threads} wall {wall:.4f} per-thread {results}")
EOF"}

