#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *out, *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} job;

void *worker(void *arg) {
    job *j = arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

int main() {
    size_t N = 40000000;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N);
    memset(pt, 1, N);
    unsigned int key[8] = {1,2,3,4,5,6,7,8};

    for (int threads = 1; threads <= 8; threads *= 2) {
        // align chunks to 64
        size_t chunk = (N / threads) & ~63ULL;
        pthread_t th[16];
        job jobs[16];
        double t0 = now();
        int reps = 3;
        for (int r = 0; r < reps; r++) {
            size_t off = 0;
            for (int t = 0; t < threads; t++) {
                size_t len = (t == threads-1) ? (N - off) : chunk;
                jobs[t].out = ct + off;
                jobs[t].in = pt + off;
                jobs[t].len = len;
                memcpy(jobs[t].key, key, 32);
                memset(jobs[t].counter, 0, 16);
                jobs[t].counter[0] = (unsigned int)(off / 64);
                pthread_create(&th[t], NULL, worker, &jobs[t]);
                off += len;
            }
            for (int t = 0; t < threads; t++) pthread_join(th[t], NULL);
        }
        double dt = (now() - t0) / reps;
        printf("threads %d  %.4f s  %.1f MB/s\n", threads, dt, (N/1e6)/dt);
    }
    return 0;
}
EOF
