#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct { void *ctx; unsigned char *data; size_t n; } job;
void *worker(void *a) {
    job *j = a;
    Poly1305_Update(j->ctx, j->data, j->n);
    return NULL;
}

int main() {
    size_t N = 40000000;
    unsigned char *data = malloc(N);
    memset(data, 7, N);
    unsigned char key[32] = {1,2,3};
    size_t sz = Poly1305_ctx_size();

    // serial
    void *ctx = malloc(sz+64);
    unsigned char mac[16];
    double t0 = now();
    for (int r = 0; r < 3; r++) {
        Poly1305_Init(ctx, key);
        Poly1305_Update(ctx, data, N);
        Poly1305_Final(ctx, mac);
    }
    printf("serial %.4f\n", (now()-t0)/3);

    // 4 threads each hashing N/4 independently (upper bound, not combinable directly)
    int threads = 4;
    pthread_t th[8]; job jobs[8]; void *ctxs[8];
    for (int t = 0; t < threads; t++) { ctxs[t] = malloc(sz+64); Poly1305_Init(ctxs[t], key); }
    t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        size_t chunk = N/threads;
        for (int t = 0; t < threads; t++) {
            Poly1305_Init(ctxs[t], key);
            jobs[t].ctx = ctxs[t]; jobs[t].data = data + t*chunk; jobs[t].n = chunk;
            pthread_create(&th[t], NULL, worker, &jobs[t]);
        }
        for (int t = 0; t < threads; t++) pthread_join(th[t], NULL);
    }
    printf("4 independent %.4f\n", (now()-t0)/reps);

    // streaming single with 256-byte updates (cache-hot simulation)
    t0 = now();
    Poly1305_Init(ctx, key);
    for (size_t off = 0; off < N; off += 256)
        Poly1305_Update(ctx, data+off, 256);
    Poly1305_Final(ctx, mac);
    printf("256B updates %.4f\n", now()-t0);

    // 4096 updates
    t0 = now();
    Poly1305_Init(ctx, key);
    for (size_t off = 0; off < N; off += 4096)
        Poly1305_Update(ctx, data+off, 4096);
    Poly1305_Final(ctx, mac);
    printf("4K updates %.4f\n", now()-t0);
    return 0;
}
