{"command":"cat > _bench/bench_full.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define THREADS 4

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct {
    pthread_mutex_t mu;
    pthread_cond_t cv_go, cv_done;
    int go, quit, done_count;
    unsigned char *out, *in;
    size_t off, len;
    unsigned int key[8];
    unsigned int counter0;
    int id;
} pool_t;

static pool_t P;

void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    unsigned int counter[4];
    while (1) {
        pthread_mutex_lock(&P.mu);
        while (!P.go && !P.quit) pthread_cond_wait(&P.cv_go, &P.mu);
        if (P.quit) { pthread_mutex_unlock(&P.mu); break; }
        size_t off = P.off + id * (P.len / THREADS); // placeholder, real split below
        // each thread computes its own slice from shared params
        size_t total = P.len;
        size_t chunk = (total / THREADS) & ~63ULL;
        size_t myoff, mylen;
        if (id == THREADS-1) { myoff = id * chunk; mylen = total - myoff; }
        else { myoff = id * chunk; mylen = chunk; }
        unsigned char *out = P.out + myoff;
        unsigned char *in = P.in + myoff;
        unsigned int key[8]; memcpy(key, P.key, 32);
        counter[0] = P.counter0 + (unsigned int)(myoff / 64);
        counter[1] = 0; counter[2] = 0; counter[3] = 0;
        pthread_mutex_unlock(&P.mu);

        ChaCha20_ctr32(out, in, mylen, key, counter);

        pthread_mutex_lock(&P.mu);
        P.done_count++;
        if (P.done_count == THREADS) {
            P.go = 0;
            pthread_cond_signal(&P.cv_done);
        }
        pthread_mutex_unlock(&P.mu);
    }
    return NULL;
}

int main() {
    size_t N = 40960000;
    // align up
    unsigned char *pt = aligned_alloc(64, N);
    unsigned char *ct = aligned_alloc(64, N);
    memset(pt, 1, N);
    unsigned int key[8];
    for (int i = 0; i < 8; i++) key[i] = i+1;

    pthread_mutex_init(&P.mu, NULL);
    pthread_cond_init(&P.cv_go, NULL);
    pthread_cond_init(&P.cv_done, NULL);
    P.go = 0; P.quit = 0; P.done_count = 0;
