// 4-block AVX2 ChaCha20 (8 rounds unrolled x2 = 20 rounds), keystream XOR
#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static inline __m256i rotl32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

// quarter round on columns (a,b,c,d) of 8 lanes? We'll do 4 blocks = 4 lanes of 128-bit state.
// Layout: 4 blocks, each state word is a 32-bit lane. We keep 16 ymm? 
// Better: 4 independent blocks stored as 16 __m128i is scalar-ish.
// Standard approach: each of 16 state words is a __m256i holding that word across 8 blocks.
// Let's do 8 blocks at a time (256-bit / 32 = 8).

#define QR(a,b,c,d) \
    a = _mm256_add_epi32(a, b); d = rotl32(_mm256_xor_si256(d, a), 16); \
    c = _mm256_add_epi32(c, d); b = rotl32(_mm256_xor_si256(b, c), 12); \
    a = _mm256_add_epi32(a, b); d = rotl32(_mm256_xor_si256(d, a), 8); \
    c = _mm256_add_epi32(c, d); b = rotl32(_mm256_xor_si256(b, c), 7);

void chacha20_8blocks(unsigned char *out, const unsigned char *in,
                      const unsigned int key[8], unsigned int counter) {
    // constants
    __m256i s0 = _mm256_set1_epi32(0x61707865);
    __m256i s1 = _mm256_set1_epi32(0x3320646e);
    __m256i s2 = _mm256_set1_epi32(0x79622d32);
    __m256i s3 = _mm256_set1_epi32(0x6b206574);
    __m256i s4 = _mm256_set1_epi32(key[0]);
    __m256i s5 = _mm256_set1_epi32(key[1]);
    __m256i s6 = _mm256_set1_epi32(key[2]);
    __m256i s7 = _mm256_set1_epi32(key[3]);
    __m256i s8 = _mm256_set1_epi32(key[4]);
    __m256i s9 = _mm256_set1_epi32(key[5]);
    __m256i s10 = _mm256_set1_epi32(key[6]);
    __m256i s11 = _mm256_set1_epi32(key[7]);
    __m256i s12 = _mm256_set_epi32(counter+7, counter+6, counter+5, counter+4,
                                   counter+3, counter+2, counter+1, counter+0);
    __m256i s13 = _mm256_setzero_si256();
    __m256i s14 = _mm256_setzero_si256();
    __m256i s15 = _mm256_setzero_si256();

    __m256i x0=s0,x1=s1,x2=s2,x3=s3,x4=s4,x5=s5,x6=s6,x7=s7;
    __m256i x8=s8,x9=s9,x10=s10,x11=s11,x12=s12,x13=s13,x14=s14,x15=s15;

    for (int i = 0; i < 10; i++) {
        // column rounds
        QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
        // diagonal rounds
        QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
    }
    x0=_mm256_add_epi32(x0,s0); x1=_mm256_add_epi32(x1,s1);
    x2=_mm256_add_epi32(x2,s2); x3=_mm256_add_epi32(x3,s3);
    x4=_mm256_add_epi32(x4,s4); x5=_mm256_add_epi32(x5,s5);
    x6=_mm256_add_epi32(x6,s6); x7=_mm256_add_epi32(x7,s7);
    x8=_mm256_add_epi32(x8,s8); x9=_mm256_add_epi32(x9,s9);
    x10=_mm256_add_epi32(x10,s10); x11=_mm256_add_epi32(x11,s11);
    x12=_mm256_add_epi32(x12,s12); x13=_mm256_add_epi32(x13,s13);
    x14=_mm256_add_epi32(x14,s14); x15=_mm256_add_epi32(x15,s15);

    // transpose 8x16 matrix of 32-bit words into 8 sequential blocks of 64 bytes.
    // Each block b consists of words (x0[b], x1[b], ..., x15[b]).
    // We'll store via extract. This is the slow part potentially.
    // Use a straightforward extract for correctness first.
    __m256i rows[16] = {x0,x1,x2,x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14,x15};
    uint32_t tmp[8];
    for (int w = 0; w < 16; w++) {
        _mm256_storeu_si256((__m256i*)tmp, rows[w]);
        for (int b = 0; b < 8; b++) {
            uint32_t v = tmp[b];
            unsigned char *dst = out + b*64 + w*4;
            const unsigned char *src = in + b*64 + w*4;
            dst[0] = src[0] ^ (v & 0xff);
            dst[1] = src[1] ^ ((v >> 8) & 0xff);
            dst[2] = src[2] ^ ((v >> 16) & 0xff);
            dst[3] = src[3] ^ ((v >> 24) & 0xff);
        }
    }
}

void chacha20_xor(unsigned char *out, const unsigned char *in, size_t len,
                  const unsigned int key[8], unsigned int counter) {
    size_t blocks = len / 512; // 8*64
    for (size_t i = 0; i < blocks; i++) {
        chacha20_8blocks(out + i*512, in + i*512, key, counter);
        counter += 8;
    }
    // tail ignored for bench
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

// reference
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);

int main() {
