    N = N & ~511ULL;
    unsigned char *pt = aligned_alloc(64, N);
    unsigned char *ct = aligned_alloc(64, N);
    unsigned char *ref = aligned_alloc(64, N);
    memset(pt, 0x5a, N);
    unsigned int key[8] = {0x03020100,0x07060504,0x0b0a0908,0x0f0e0d0c,
                           0x13121110,0x17161514,0x1b1a1918,0x1f1e1d1c};
    unsigned int counter[4] = {1,0,0,0};

    ChaCha20_ctr32(ref, pt, N, key, counter);
    chacha20_xor(ct, pt, N, key, 1);
    if (memcmp(ct, ref, N) != 0) {
        // find first diff
        for (size_t i = 0; i < N; i++) if (ct[i] != ref[i]) {
            printf("MISMATCH at %zu: got %02x exp %02x\n", i, ct[i], ref[i]);
            break;
        }
    } else printf("MATCH\n");

    // bench
    for (int i = 0; i < 4; i++) {
        double t0 = now();
        chacha20_xor(ct, pt, N, key, 1);
        double t = now()-t0;
        printf("avx2 %.3f ms  %.1f MB/s\n", t*1000, (N/1e6)/t);
    }
    for (int i = 0; i < 3; i++) {
        double t0 = now();
        ChaCha20_ctr32(ref, pt, N, key, counter);
        double t = now()-t0;
        printf("openssl %.3f ms  %.1f MB/s\n", t*1000, (N/1e6)/t);
    }
    return 0;
}
