// After column-major store we want each block's 16 bytes contiguous.
// rows r0..r3 each hold word W of 8 blocks.
// We want out block b: r0[b], r1[b], r2[b], r3[b] (16 bytes).
static inline void store_transpose4(__m256i r0, __m256i r1, __m256i r2, __m256i r3,
                                    unsigned char *out) {
    // interleave 32-bit
    __m256i a0 = _mm256_unpacklo_epi32(r0, r1); // b0:w0,w1 b1:w0,w1 | b4...
    __m256i a1 = _mm256_unpackhi_epi32(r0, r1);
    __m256i a2 = _mm256_unpacklo_epi32(r2, r3);
    __m256i a3 = _mm256_unpackhi_epi32(r2, r3);
    __m256i b0 = _mm256_unpacklo_epi64(a0, a2); // b0: w0,w1,w2,w3 (16B) b1:...
    __m256i b1 = _mm256_unpackhi_epi64(a0, a2);
    __m256i b2 = _mm256_unpacklo_epi64(a1, a3);
    __m256i b3 = _mm256_unpackhi_epi64(a1, a3);
    // Now b0 = [block0 | block1] but in low 128 and ... actually unpacklo_epi64
    // of 256-bit operates within lanes. So low 128 of b0 = block0, high 128 = block4.
    // Need to permute across lanes.
    // b0: lane0=block0, lane1=block4
    // b1: lane0=block1, lane1=block5
    // b2: lane0=block2, lane1=block6
    // b3: lane0=block3, lane1=block7
    __m256i p0 = _mm256_permute2x128_si256(b0, b1, 0x20); // block0, block1
