// Scalar poly1305 with 26-bit limbs? Let's do 64-bit delayed reduction, 2 blocks at a time.
// Reference implementation adapted from public domain poly1305-donna (32-bit) — known fast.

typedef struct {
    uint32_t r[5];
    uint32_t h[5];
    uint32_t pad[4];
    size_t leftover;
    unsigned char buffer[16];
    unsigned char final;
} poly1305_state;

static uint32_t U8TO32(const unsigned char *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1]<<8) | ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24);
}

static void poly1305_init(poly1305_state *st, const unsigned char key[32]) {
    st->r[0] = U8TO32(key+0) & 0x3ffffff;
    st->r[1] = (U8TO32(key+3) >> 2) & 0x3ffff03;
    st->r[2] = (U8TO32(key+6) >> 4) & 0x3ffc0ff;
    st->r[3] = (U8TO32(key+9) >> 6) & 0x3f03fff;
