        uint64_t d0 = ((uint64_t)h0) + (U8TO32(m+0) & 0x3ffffff);
        uint64_t d1 = ((uint64_t)h1) + ((U8TO32(m+3) >> 2) & 0x3ffffff);
        uint64_t d2 = ((uint64_t)h2) + ((U8TO32(m+6) >> 4) & 0x3ffffff);
        uint64_t d3 = ((uint64_t)h3) + ((U8TO32(m+9) >> 6) & 0x3ffffff);
        uint64_t d4 = ((uint64_t)h4) + ((U8TO32(m+12) >> 8) | hibit);

