        c = d0*r0 + d1*s4 + d2*s3 + d3*s2 + d4*s1; h0 = (uint32_t)c & 0x3ffffff; c >>= 26;
        c += d0*r1 + d1*r0 + d2*s4 + d3*s3 + d4*s2; h1 = (uint32_t)c & 0x3ffffff; c >>= 26;
        c += d0*r2 + d1*r1 + d2*r0 + d3*s4 + d4*s3; h2 = (uint32_t)c & 0x3ffffff; c >>= 26;
