        c += d0*r4 + d1*r3 + d2*r2 + d3*r1 + d4*r0; h4 = (uint32_t)c & 0x3ffffff; c >>= 26;
        h0 += (uint32_t)c * 5; c = h0 >> 26; h0 &= 0x3ffffff; h1 += (uint32_t)c;

        m += 16; bytes -= 16;
    }
    st->h[0]=h0; st->h[1]=h1; st->h[2]=h2; st->h[3]=h3; st->h[4]=h4;
}

