    // Let's recompute mask the donna way
    g0=h0+5; c=g0>>26; g0&=0x3ffffff;
    g1=h1+c; c=g1>>26; g1&=0x3ffffff;
    g2=h2+c; c=g2>>26; g2&=0x3ffffff;
    g3=h3+c; c=g3>>26; g3&=0x3ffffff;
    g4=h4+c - (1UL<<26);
    mask = (g4 >> 31) - 1;
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    uint64_t f0 = ((h0) | (h1 << 26)) + (uint64_t)st->pad[0];
    uint64_t f1 = ((h1 >> 6) | (h2 << 20)) + (uint64_t)st->pad[1];
    uint64_t f2 = ((h2 >> 12) | (h3 << 14)) + (uint64_t)st->pad[2];
    uint64_t f3 = ((h3 >> 18) | (h4 << 8)) + (uint64_t)st->pad[3];
    f1 += f0 >> 32; f2 += f1 >> 32; f3 += f2 >> 32;
    mac[0]=f0; mac[1]=f0>>8; mac[2]=f0>>16; mac[3]=f0>>24;
    mac[4]=f1; mac[5]=f1>>8; mac[6]=f1>>16; mac[7]=f1>>24;
    mac[8]=f2; mac[9]=f2>>8; mac[10]=f2>>16; mac[11]=f2>>24;
    mac[12]=f3; mac[13]=f3>>8; mac[14]=f3>>16; mac[15]=f3>>24;
}

