// 2-way SSE2 poly1305 (26-bit limbs), processes 32 bytes/iter
#include <emmintrin.h>
#include <tmmintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static inline uint32_t U8TO32(const unsigned char *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1]<<8) | ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24);
}

// We compute two independent accumulators for even/odd blocks, then combine.
// h = (...((m0*r + m1)*r + m2)*r ...) 
// even blocks contribute with r^2 each step; odd with r^2.
// h = h_even * r + h_odd, after processing pairs with r^2.
// Standard trick (poly1305-donna sse2): process 2 blocks per iteration with r and r^2.

typedef struct {
    uint32_t r[5];
    uint32_t h[5];
    uint32_t pad[4];
} poly_st;

static void poly_init(poly_st *st, const unsigned char key[32]) {
    st->r[0] = U8TO32(key+0) & 0x3ffffff;
    st->r[1] = (U8TO32(key+3) >> 2) & 0x3ffff03;
    st->r[2] = (U8TO32(key+6) >> 4) & 0x3ffc0ff;
    st->r[3] = (U8TO32(key+9) >> 6) & 0x3f03fff;
    st->r[4] = (U8TO32(key+12) >> 8) & 0x00fffff;
    st->h[0]=st->h[1]=st->h[2]=st->h[3]=st->h[4]=0;
    st->pad[0]=U8TO32(key+16); st->pad[1]=U8TO32(key+20);
    st->pad[2]=U8TO32(key+24); st->pad[3]=U8TO32(key+28);
}

// Multiply h by r, add m (26-bit limbs). Scalar, used for tail and for precomputing r^2.
static void mul_add(uint32_t h[5], const uint32_t r[5], const uint32_t m[5], int do_add) {
    uint32_t r0=r[0],r1=r[1],r2=r[2],r3=r[3],r4=r[4];
    uint32_t s1=r1*5,s2=r2*5,s3=r3*5,s4=r4*5;
    uint64_t d0=h[0], d1=h[1], d2=h[2], d3=h[3], d4=h[4];
    if (do_add) { d0+=m[0]; d1+=m[1]; d2+=m[2]; d3+=m[3]; d4+=m[4]; }
    uint64_t c;
    c = d0*r0 + d1*s4 + d2*s3 + d3*s2 + d4*s1; h[0]=(uint32_t)c & 0x3ffffff; c>>=26;
    c += d0*r1 + d1*r0 + d2*s4 + d3*s3 + d4*s2; h[1]=(uint32_t)c & 0x3ffffff; c>>=26;
    c += d0*r2 + d1*r1 + d2*r0 + d3*s4 + d4*s3; h[2]=(uint32_t)c & 0x3ffffff; c>>=26;
    c += d0*r3 + d1*r2 + d2*r1 + d3*r0 + d4*s4; h[3]=(uint32_t)c & 0x3ffffff; c>>=26;
    c += d0*r4 + d1*r3 + d2*r2 + d3*r1 + d4*r0; h[4]=(uint32_t)c & 0x3ffffff; c>>=26;
    h[0] += (uint32_t)c * 5; c = h[0]>>26; h[0] &= 0x3ffffff; h[1] += (uint32_t)c;
}

static void load_block(uint32_t m[5], const unsigned char *p) {
    m[0] = U8TO32(p+0) & 0x3ffffff;
    m[1] = (U8TO32(p+3) >> 2) & 0x3ffffff;
    m[2] = (U8TO32(p+6) >> 4) & 0x3ffffff;
    m[3] = (U8TO32(p+9) >> 6) & 0x3ffffff;
    m[4] = (U8TO32(p+12) >> 8) | (1u<<24);
}

// SSE2 2-block: maintain h0 (even, multiplied by r^2) and h1 (odd, multiplied by r^2), 
// then final combine h = h0*r + h1? Let's derive.
// After pairs (m0,m1), (m2,m3), ...
// h = (((m0*r + m1)*r + m2)*r + m3)*r ...
//   = (m0*r^2 + m1*r + m2)*r^2 + m3*r + ... 
// Let he accumulate even blocks with factor r^2, ho accumulate odd blocks with factor r^2.
// he = m0 + m2*r^{-2}? no.
// he_final * r^2^{n/2} style:
// h = he * r + ho, where
// he = m0*r^2^{k-1} + m2*r^2^{k-2} + ... + m_{2k-2}
// ho = m1*r^2^{k-1} + m3*r^2^{k-2} + ... + m_{2k-1}
// Yes: each step he = he*r^2 + m_even; ho = ho*r^2 + m_odd; then h = he*r + ho.
// But the LAST multiply by r (the one after last block) is included? 
// Full: h = (...((m0)*r + m1)*r + m2)*r + m3)*r
// = he*r + ho, with he, ho as above, AND a final *r is already in the formula? 
// (...+ m3)*r = he*r^2 + ho*r = (he*r + ho)*r. So we need one more *r.
// h = (he * r + ho) * r.
// Check k=1 (2 blocks): he=m0, ho=m1. h should be (m0*r + m1)*r = m0*r^2 + m1*r.
// (he*r + ho)*r = m0*r^2 + m1*r. Good.
// We'll do the two-block loop then two scalar multiplies by r at the end.

static inline __m128i m32(__m128i a, __m128i b) {
    // 32x32->64 multiply, two lanes. _mm_mul_epu32 multiplies low 32 of each 64.
    return _mm_mul_epu32(a, b);
}

static void poly_blocks_sse2(poly_st *st, const unsigned char *m, size_t bytes) {
    uint32_t r[5]; memcpy(r, st->r, sizeof r);
    // r^2
    uint32_t rr[5] = {r[0],r[1],r[2],r[3],r[4]};
    uint32_t zero[5] = {0,0,0,0,0};
    // compute r^2 = r*r (no add)
    uint32_t r2[5] = {0,0,0,0,0};
