void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define NTHREADS 4

typedef struct {
    pthread_mutex_t mu;
    pthread_cond_t cv_go, cv_done;
    int go, quit, done;
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned int key[8];
    unsigned int counter_base;
    unsigned int nonce[3];
} pool_t;

static pool_t POOL;
static pthread_t THREADS[NTHREADS];
static int POOL_READY = 0;
static void *poly_ctx = NULL;

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    unsigned int counter[4];
    unsigned int key[8];
    for (;;) {
        pthread_mutex_lock(&POOL.mu);
        while (!POOL.go && !POOL.quit)
            pthread_cond_wait(&POOL.cv_go, &POOL.mu);
        if (POOL.quit) { pthread_mutex_unlock(&POOL.mu); return NULL; }

        size_t len = POOL.len;
