        unsigned char *out = POOL.out + off;
        const unsigned char *in = POOL.in + off;
        memcpy(key, POOL.key, 32);
        counter[0] = POOL.counter_base + (unsigned int)(off >> 6);
        counter[1] = POOL.nonce[0];
        counter[2] = POOL.nonce[1];
        counter[3] = POOL.nonce[2];
        pthread_mutex_unlock(&POOL.mu);

        if (mylen) ChaCha20_ctr32(out, in, mylen, key, counter);

        pthread_mutex_lock(&POOL.mu);
        if (++POOL.done == NTHREADS) {
            POOL.go = 0;
            pthread_cond_signal(&POOL.cv_done);
        }
        pthread_mutex_unlock(&POOL.mu);
    }
}

static void ensure_init(void) {
    if (POOL_READY) return;
    pthread_mutex_init(&POOL.mu, NULL);
    pthread_cond_init(&POOL.cv_go, NULL);
    pthread_cond_init(&POOL.cv_done, NULL);
    POOL.go = POOL.quit = POOL.done = 0;
    for (int i = 0; i < NTHREADS; i++)
        pthread_create(&THREADS[i], NULL, worker, (void *)(intptr_t)i);
    poly_ctx = malloc(Poly1305_ctx_size() + 64);
    POOL_READY = 1;
}

static void chacha_parallel(unsigned char *out, const unsigned char *in, size_t len,
                            const unsigned int key[8], unsigned int counter_base,
                            const unsigned int nonce[3]) {
    pthread_mutex_lock(&POOL.mu);
    POOL.out = out;
    POOL.in = in;
    POOL.len = len;
