    POOL.counter_base = counter_base;
    POOL.nonce[0] = nonce[0];
    POOL.nonce[1] = nonce[1];
    POOL.nonce[2] = nonce[2];
    POOL.done = 0;
    POOL.go = 1;
    pthread_cond_broadcast(&POOL.cv_go);
    while (POOL.done < NTHREADS)
        pthread_cond_wait(&POOL.cv_done, &POOL.mu);
    pthread_mutex_unlock(&POOL.mu);
}

static inline uint32_t load32(const unsigned char *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static inline void store64(unsigned char *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (unsigned char)(v >> (8 * i));
}

void chacha20poly1305_encrypt(const unsigned char key_bytes[32],
                              const unsigned char nonce_bytes[12],
                              const unsigned char *aad, size_t aad_len,
                              const unsigned char *pt, size_t pt_len,
                              unsigned char *ct, unsigned char tag[16]) {
