    Poly1305_Init(poly_ctx, block0);
    if (aad && aad_len) Poly1305_Update(poly_ctx, aad, aad_len);
    size_t aad_pad = (16 - (aad_len & 15)) & 15;
    unsigned char zpad[16] = {0};
    if (aad_pad) Poly1305_Update(poly_ctx, zpad, aad_pad);
    if (pt_len) Poly1305_Update(poly_ctx, ct, pt_len);
    size_t ct_pad = (16 - (pt_len & 15)) & 15;
    if (ct_pad) Poly1305_Update(poly_ctx, zpad, ct_pad);
    unsigned char lens[16];
    store64(lens, (uint64_t)aad_len);
    store64(lens + 8, (uint64_t)pt_len);
    Poly1305_Update(poly_ctx, lens, 16);
    Poly1305_Final(poly_ctx, tag);
}
