// Transpose one 128-bit-lane group? We store 4 blocks (one ymm holds 4 blocks of one row).
// After rounds, for each of 4 block-groups, rows a,b,c,d hold the 4 state rows across 4 blocks.
// We want each block's 64 bytes contiguous: block i = row0[i]||row1[i]||row2[i]||row3[i] (16 bytes each).
static inline void transpose_store(__m256i r0, __m256i r1, __m256i r2, __m256i r3, unsigned char *out) {
    // r0 holds 4 blocks x 4 words (the first row of each block) within the ymm (2 lanes x 4 words = 2 blocks per lane? )
    // Layout of a __m256i row after shuffle-based chacha: each 128-bit lane holds one block's row (4 words).
    // So r0 = [block0 row0 | block1 row0], r1 = [block0 row1 | block1 row1]? NO.
    // We process 8 blocks. Let's define:
    // a0 holds row0 of blocks 0..3? With shuffle_epi32 operating within 128-bit lanes,
    // each 128-bit lane is an independent block. A ymm has 2 lanes => 2 blocks per register.
    // 4 registers a0..a3 => 8 blocks. Each register holds 2 blocks' row0.
    // So a0 = [block0_row0 | block1_row0] (128 bits each).
    // To get block0's 64 bytes: a0.lo, b0.lo, c0.lo, d0.lo.
    __m128i a_lo=_mm256_castsi256_si128(r0), a_hi=_mm256_extracti128_si256(r0,1);
    __m128i b_lo=_mm256_castsi256_si128(r1), b_hi=_mm256_extracti128_si256(r1,1);
    __m128i c_lo=_mm256_castsi256_si128(r2), c_hi=_mm256_extracti128_si256(r2,1);
    __m128i d_lo=_mm256_castsi256_si128(r3), d_hi=_mm256_extracti128_si256(r3,1);
    _mm_storeu_si128((__m128i*)(out+0),  a_lo);
    _mm_storeu_si128((__m128i*)(out+16), b_lo);
    _mm_storeu_si128((__m128i*)(out+32), c_lo);
    _mm_storeu_si128((__m128i*)(out+48), d_lo);
    _mm_storeu_si128((__m128i*)(out+64), a_hi);
    _mm_storeu_si128((__m128i*)(out+80), b_hi);
    _mm_storeu_si128((__m128i*)(out+96), c_hi);
    _mm_storeu_si128((__m128i*)(out+112),d_hi);
}

