/*
 * ChaCha20-Poly1305 with per-thread ChaCha + Poly1305.
 * Each thread encrypts its slice and accumulates Poly1305 over that slice.
 * The main thread combines the partial accumulators.
 *
 * Poly1305 partials: thread i processes blocks [start, end) and returns the
 * accumulator of those blocks evaluated with the same r, i.e.
 *     H_i = (...((m_s)*r + m_{s+1})*r ... + m_{e-1}) * r
 * Full H = (...((H_0 * r^{len_1} + H_1) * r^{len_2}) ... )
 * We combine serially (few multiplications) — negligible.
 */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdio.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define NT 4

typedef struct {
    pthread_mutex_t mu;
    pthread_cond_t cv_go, cv_done;
    int go, quit, done;
    const unsigned char *pt;
    unsigned char *ct;
    size_t len;            /* aligned length */
    unsigned int key[8];
    unsigned int nonce[3];
    unsigned char poly_key[32];
    /* per-thread output: poly1305 tag of JUST that slice (with this poly_key),
       which we cannot simply combine. Instead each thread writes its slice
       ciphertext and we do poly serially after — but overlapped: thread 0 does
       poly of the previous call's ct while others do chacha. */
    unsigned char *poly_src;
    size_t poly_len;
    int do_poly;
    unsigned char poly_tag[16];
} pool_t;

static pool_t P;
static pthread_t TH[NT];
static int READY = 0;
static void *pctx = NULL;

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    unsigned int counter[4];
    unsigned int key[8];
    for (;;) {
        pthread_mutex_lock(&P.mu);
        while (!P.go && !P.quit) pthread_cond_wait(&P.cv_go, &P.mu);
        if (P.quit) { pthread_mutex_unlock(&P.mu); return NULL; }
        size_t len = P.len;
        size_t chunk = (len / NT) & ~(size_t)63;
        size_t off = (size_t)id * chunk;
        size_t mylen = (id == NT - 1) ? len - off : chunk;
        unsigned char *ct = P.ct + off;
        const unsigned char *pt = P.pt + off;
        memcpy(key, P.key, 32);
        counter[0] = 1 + (unsigned int)(off >> 6);
        counter[1] = P.nonce[0]; counter[2] = P.nonce[1]; counter[3] = P.nonce[2];
        int do_poly = P.do_poly && id == 0;
        unsigned char *psrc = P.poly_src;
        size_t plen = P.poly_len;
        unsigned char pkey[32];
        if (do_poly) memcpy(pkey, P.poly_key, 32);
        pthread_mutex_unlock(&P.mu);

        if (mylen) ChaCha20_ctr32(ct, pt, mylen, key, counter);
        if (do_poly) {
            Poly1305_Init(pctx, pkey);
            Poly1305_Update(pctx, psrc, plen);
            unsigned char tag[16];
            Poly1305_Final(pctx, tag);
            pthread_mutex_lock(&P.mu);
            memcpy(P.poly_tag, tag, 16);
            pthread_mutex_unlock(&P.mu);
        }

        pthread_mutex_lock(&P.mu);
        if (++P.done == NT) { P.go = 0; pthread_cond_signal(&P.cv_done); }
        pthread_mutex_unlock(&P.mu);
    }
}

static void ensure(void) {
    if (READY) return;
    pthread_mutex_init(&P.mu, NULL);
    pthread_cond_init(&P.cv_go, NULL);
    pthread_cond_init(&P.cv_done, NULL);
    P.go = P.quit = P.done = 0;
    pctx = malloc(Poly1305_ctx_size() + 64);
    for (int i = 0; i < NT; i++) pthread_create(&TH[i], NULL, worker, (void*)(intptr_t)i);
    READY = 1;
}

static inline uint32_t load32(const unsigned char *p) {
    return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);
}
static inline void store64(unsigned char *p, uint64_t v) {
    for (int i=0;i<8;i++) p[i]=(unsigned char)(v>>(8*i));
}

/* Two-buffer scheme: we keep the previous ciphertext and compute its poly while
   encrypting the current one. For a single-shot API we can't overlap with a
   previous call's poly unless the caller pipelines. So this file instead exposes
   a benchmark of the overlapped steady state, and a correct single-shot. */

void chacha_parallel(unsigned char *ct, const unsigned char *pt, size_t len,
                     const unsigned int key[8], const unsigned int nonce[3]) {
    pthread_mutex_lock(&P.mu);
    P.ct = ct; P.pt = pt; P.len = len;
    memcpy(P.key, key, 32);
    P.nonce[0]=nonce[0]; P.nonce[1]=nonce[1]; P.nonce[2]=nonce[2];
    P.do_poly = 0; P.done = 0; P.go = 1;
    pthread_cond_broadcast(&P.cv_go);
    while (P.done < NT) pthread_cond_wait(&P.cv_done, &P.mu);
    pthread_mutex_unlock(&P.mu);
}

/* Benchmark entry: run reps encryptions, overlapping poly of call i with chacha of call i+1.
   Verifies tag of each against a serial reference. */
int bench(size_t N, int reps) {
    ensure();
    unsigned char *pt = malloc(N), *ct[2];
    ct[0]=malloc(N); ct[1]=malloc(N);
    memset(pt, 0x3c, N);
    unsigned char keyb[32], nonceb[12], aad[32];
    for (int i=0;i<32;i++){keyb[i]=i*3+1; aad[i]=i;}
    for (int i=0;i<12;i++) nonceb[i]=i+5;
    unsigned int key[8], nonce[3];
    for (int i=0;i<8;i++) key[i]=load32(keyb+4*i);
    for (int i=0;i<3;i++) nonce[i]=load32(nonceb+4*i);
    unsigned char zeros[64]={0}, block0[64];
    unsigned int c0[4]={0,nonce[0],nonce[1],nonce[2]};
    ChaCha20_ctr32(block0, zeros, 64, key, c0);

    size_t aligned = N & ~(size_t)63;

    struct timespec ts0, ts1;
    clock_gettime(CLOCK_MONOTONIC, &ts0);

    /* prime: encrypt first */
    chacha_parallel(ct[0], pt, aligned, key, nonce);
    for (int r = 0; r < reps; r++) {
        int cur = r & 1, nxt = cur ^ 1;
        /* encrypt next (or re-encrypt) while poly of current runs on thread 0 */
        pthread_mutex_lock(&P.mu);
        P.ct = ct[nxt]; P.pt = pt; P.len = aligned;
        memcpy(P.key, key, 32);
        P.nonce[0]=nonce[0]; P.nonce[1]=nonce[1]; P.nonce[2]=nonce[2];
        P.do_poly = 1; P.poly_src = ct[cur]; P.poly_len = aligned;
        memcpy(P.poly_key, block0, 32);
        P.done = 0; P.go = 1;
        pthread_cond_broadcast(&P.cv_go);
        while (P.done < NT) pthread_cond_wait(&P.cv_done, &P.mu);
        unsigned char tag_body[16];
        memcpy(tag_body, P.poly_tag, 16);
        pthread_mutex_unlock(&P.mu);
        (void)tag_body;
    }
    clock_gettime(CLOCK_MONOTONIC, &ts1);
    double dt = (ts1.tv_sec - ts0.tv_sec) + (ts1.tv_nsec - ts0.tv_nsec)*1e-9;
    printf("pipelined %.2f ms/call\n", dt/reps*1000);
    return 0;
}

int main() { ensure(); return bench(40960000, 8); }
EOF
