# Design the partial-poly combine and verify with integers, then implement in C using
# OpenSSL only for the bulk and a tiny limb routine for the O(threads) combine.
P = 2**130 - 5
def poly_raw(blocks, r):
    """returns accumulator AFTER processing, i.e. (...((m0)*r+m1)*r...+m_last)*r, no +s, no mod clamp."""
    h = 0
    for b in blocks:
        h = (h + b) % P * r % P
    return h

